    ARRAY['dinamica-de-confianza', 'afectividad', 'panolines', 'interior', 'exterior'],
    $json${"unidades": ["manada", "compañía", "tropa", "avanzada", "clan"], "duracion": "15 minutos", "cantidad": "12 participantes", "lugares": ["Interior", "Exterior", "campo delimitado"], "materiales": ["Pañolines", "Sin Materiales"], "areas": ["afectividad", "sociabilidad", "carácter"], "objetivos": ["Estimular la confianza", "Crear un clima de pertenencia", "Fomentar un entorno de confianza", "Introspección"], "justificacion_areas": "El Árbol y el Viento fortalece la afectividad al brindar un espacio seguro para vencer temores y elevar la confianza en uno mismo. Desarrolla la sociabilidad al afianzar la empatía y la contención cuidadosa entre iguales, y ejercita el carácter al cultivar la serenidad, la desinhibición y la desinteresada entrega al grupo.", "variaciones": "<b>El Bosque Soplado por el Viento:</b> Se forman varios círculos simultáneos de 5 a 6 participantes para que la dinámica sea más íntima y todos los scouts pasen al centro en menor tiempo.\n\n<b>Balanceo con Pañolín:</b> El participante del centro utiliza su <b>pañolín</b> a modo de venda para reforzar la desinhibición y el abandono voluntario del control visual.\n\n<b>Cálida Recepción:</b> Al terminar el mecido, el círculo se estrecha lentamente abrazando de forma coordinada al participante del centro antes de que abra los ojos.", "recomendaciones": "<b>Seguridad Ante Todo:</b> Asegurar que las palmas de los compañeros del círculo estén siempre listas y firmes a la altura del pecho y espalda. Queda estrictamente prohibido hacer movimientos bruscos o soltar al participante.\n\n<b>Silencio y Concentración:</b> Crear una atmósfera de tranquilidad previa. El tono de voz del dirigente facilitador debe ser pausado y sereno.\n\n<b>Participación Voluntaria:</b> Respetar a aquellos participantes que sientan timidez inicial, permitiéndoles primero ser parte del círculo exterior antes de pasar al centro.", "objetivos_educativos": [{"id": "041daaea-c4a7-472b-a613-951bd25cfa85", "texto": "Reconozco y acepto mis errores.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "Infancia Media", "area": "Carácter", "unidad": "Manada", "como_se_cumple": "Superando el temor inicial al soltar el control y dejarme balancear por mis hermanos lobatos."}, {"id": "b66418eb-3eee-466e-9836-457b3bb922cc", "texto": "Sé lo que puedo hacer y lo que no puedo hacer.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "Infancia Tardía", "area": "Carácter", "unidad": "Manada", "como_se_cumple": "Reconociendo mis emociones y sintiéndome seguro en el centro del círculo."}, {"id": "62876ebe-214f-4caf-b164-664e12fd30ae", "texto": "Me gusta participar en actividades que me ayudan a conocerme.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "11 a 13 años", "area": "Carácter", "unidad": "Tropa", "como_se_cumple": "Aceptando mis vulnerabilidades y confiando en el sostén fraterno de la patrulla."}, {"id": "c380e11a-571d-4617-924c-aa933ae30138", "texto": "Soy capaz de criticarme.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "13 a 15 años", "area": "Carácter", "unidad": "Tropa", "como_se_cumple": "Fortaleciendo la autoestima al experimentar el cuidado y la protección de mis pares."}, {"id": "3a35ddd8-f6dc-4e00-a04d-107a0825bd99", "texto": "Escucho las críticas que me hacen los demás y reflexiono sobre ellas.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "11 a 13 años", "area": "Carácter", "unidad": "Compañía", "como_se_cumple": "Desarrollando serenidad emocional al cerrar los ojos y confiar en la unidad."}, {"id": "006c5b09-47cf-4ed8-bf25-212203261a03", "texto": "Sé que soy capaz de hacer cosas y de hacerlas bien.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "13 a 15 años", "area": "Carácter", "unidad": "Compañía", "como_se_cumple": "Afianzando una imagen corporal y emocional positiva a través del apoyo colectivo."}, {"id": "dea08f50-52d5-4d87-ad7f-b7dbbb2702fc", "texto": "Me acepto tal como soy, sin dejar de mirarme críticamente.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "15 a 17 años", "area": "Carácter", "unidad": "Avanzada", "como_se_cumple": "Profundizando la confianza interior y el autocontrol emocional ante el grupo."}, {"id": "8f0eb7d9-c291-44f3-9551-4330c19e0cc2", "texto": "Conozco mis posibilidades y limitaciones, aceptándome con capacidad de autocrítica y manteniendo a la vez una buena imagen de mí mismo.", "texto_terminal": "Conoce sus posibilidades y limitaciones, aceptándose con capacidad de autocrítica y manteniendo a la vez una buena imagen de sí mismo.", "rango_edad": "17 a 20 años", "area": "Carácter", "unidad": "Clan", "como_se_cumple": "Cultivando la madurez afectiva y la aceptación serena de mis posibilidades personales."}, {"id": "cfa10133-c25c-4deb-aebe-a00f8fe3f7ef", "texto": "Comparto lo que tengo con mis compañeros y compañeras.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "Infancia Media", "area": "Sociabilidad", "unidad": "Manada", "como_se_cumple": "Sosteniendo con delicadeza y responsabilidad a mis compañeros en el círculo."}, {"id": "5cbe35dc-d15b-4070-9a36-5b0e652c7946", "texto": "Respeto las opiniones de los demás.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "Infancia Tardía", "area": "Sociabilidad", "unidad": "Manada", "como_se_cumple": "Velando por la seguridad de cada lobato cuando le toca ser el árbol."}, {"id": "a3d7abdf-ca3b-42b8-92b5-403958fb537c", "texto": "Procuro que respetemos a nuestras compañeros, cualquiera sea su manera de ser.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "11 a 13 años", "area": "Sociabilidad", "unidad": "Tropa", "como_se_cumple": "Ofreciendo un soporte firme y respetuoso a todos los miembros de la patrulla."}, {"id": "0d3af46a-d64c-4e59-a765-1f72dc41ba76", "texto": "Ayudo a mi patrulla en los compromisos que tomamos.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "13 a 15 años", "area": "Sociabilidad", "unidad": "Tropa", "como_se_cumple": "Fomentando un ambiente de contención mutua y cuidado solidario."}, {"id": "fce82191-77ea-444b-89d9-e33b62a323a5", "texto": "Procuro que respetemos a nuestras compañeras, cualquiera sea su manera de ser.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "11 a 13 años", "area": "Sociabilidad", "unidad": "Compañía", "como_se_cumple": "Participando activamente en la creación de un espacio de confianza y respeto."}, {"id": "944660c8-0093-4181-ba2c-5f95cc74ba47", "texto": "No me gusta cuando no se respetan los derechos humanos y lo digo.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "13 a 15 años", "area": "Sociabilidad", "unidad": "Compañía", "como_se_cumple": "Respetando la libertad y el ritmo emocional de cada participante."}, {"id": "5abfbe81-75e4-4444-b52d-38e59e8b6ec7", "texto": "Estoy siempre disponible para ayudar a los demás, incluso cuando se trata de tareas pesadas o poco agradables.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "15 a 17 años", "area": "Sociabilidad", "unidad": "Avanzada", "como_se_cumple": "Liderando con empatía la contención del grupo para generar seguridad absoluta."}, {"id": "b5a81328-5c07-41bd-a1ea-1ed401762841", "texto": "Vivo mi libertad de un modo solidario, ejerciendo mis derechos, cumpliendo mis obligaciones y defendiendo igual derecho para los demás.", "texto_terminal": "Vive su libertad de un modo solidario, ejerciendo sus derechos, cumpliendo sus obligaciones y defendiendo igual derecho para los demás.", "rango_edad": "17 a 20 años", "area": "Sociabilidad", "unidad": "Clan", "como_se_cumple": "Ejerciendo el servicio solidario garantizando el bienestar colectivo de los caminantes."}, {"id": "8c1cbf88-6e1d-496b-b789-9e0b767c8814", "texto": "Casi siempre estoy alegre.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "Infancia Media", "area": "Carácter", "unidad": "Manada", "como_se_cumple": "Disfrutando la sensación de mecerse suavemente con alegría y sin tensiones."}, {"id": "d408da3c-207d-4442-a891-8f50efbeecb1", "texto": "Enfrento las dificultades con buen ánimo.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "Infancia Tardía", "area": "Carácter", "unidad": "Manada", "como_se_cumple": "Compartiendo las impresiones de la vivencia con entusiasmo y buen ánimo."}, {"id": "4d66ed86-48ec-4801-bd0a-e5c8d023c8cd", "texto": "Enfrento y resuelvo mis dificultades con alegría.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "11 a 13 años", "area": "Carácter", "unidad": "Tropa", "como_se_cumple": "Expresando lo vivido con sinceridad y sentido del humor al finalizar el ejercicio."}, {"id": "9a38e454-f93a-40a5-9f68-e500ba7e0655", "texto": "Comparto mi alegría con mis amigos, amigos y familia.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "13 a 15 años", "area": "Carácter", "unidad": "Tropa", "como_se_cumple": "Afrontando el reto de soltarse con una actitud serena y positiva."}, {"id": "117bbf3f-7e3d-4c61-b305-821609bf2e5a", "texto": "Contribuyo al ambiente de alegría de mi Compañía.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "11 a 13 años", "area": "Carácter", "unidad": "Compañía", "como_se_cumple": "Viviendo la experiencia con tranquilidad y espontaneidad en el grupo."}, {"id": "25b24d3a-9d47-44af-b460-680508e644f3", "texto": "Soy alegre.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "13 a 15 años", "area": "Carácter", "unidad": "Compañía", "como_se_cumple": "Fomentando un clima de distensión y apertura dialogante."}, {"id": "4b2e406f-2d78-4039-9ce2-4ccb743eb553", "texto": "Soy capaz de reírme de mis propios absurdos.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "15 a 17 años", "area": "Carácter", "unidad": "Avanzada", "como_se_cumple": "Aceptando la entrega con deportividad y serenidad de carácter."}, {"id": "d716bdfb-2fea-4b96-9a46-b86d66692d45", "texto": "Enfrento la vida con alegría y sentido del humor.", "texto_terminal": "Enfrenta la vida con alegría y sentido del humor.", "rango_edad": "17 a 20 años", "area": "Carácter", "unidad": "Clan", "como_se_cumple": "Reflexionando sobre la confianza con madurez, templanza y optimismo."}]}$json$::jsonb
